    };
}vec2_t;

typedef union vec3{
    GLfloat raw[3];
    struct{
        GLfloat x, y, z; 
    };
}vec3_t;

typedef union vec4{
    GLfloat raw[4];
    struct{
        GLfloat x, y, z, w; 
    };
}vec4_t;

typedef union mat3x3{
    GLfloat raw[9];
    GLfloat cols[3][3];
    struct{
        GLfloat m0, m1, m2,
                m3, m4, m5,
                m6, m7, m8;
    };
}mat3x3_t;

typedef union mat4x4{
    GLfloat raw[16];
    GLfloat cols[4][4];
    struct{
        GLfloat m0, m1, m2, m3,
                m4, m5, m6, m7,
                m8, m9, m10,m11,
